import { gzipSync, gunzipSync } from 'node:zlib';
import { DatabaseSync } from 'node:sqlite';
let seed=17;
const text=Array.from({length:4000},()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return String.fromCodePoint(0x4e00+seed%20902)}).join('');
const receipt={ok:true,id:'11111111-1111-4111-8111-111111111111',houseId:'22222222-2222-4222-8222-222222222222',sequence:1,message:{id:'33333333-3333-4333-8333-333333333333',authorId:'44444444-4444-4444-8444-444444444444',name:'Example',text,at:1792600000000,sequence:1}};
const raw=JSON.stringify(receipt), zipped=gzipSync(raw,{level:1});
const db=new DatabaseSync(':memory:'); db.exec("PRAGMA encoding='UTF-16le';CREATE TABLE t(v TEXT)");db.prepare('INSERT INTO t VALUES(?)').run(raw);
const native=db.prepare('SELECT length(CAST(v AS BLOB)) bytes FROM t').get().bytes;
let trailingRejected=false;try{gunzipSync(Buffer.concat([zipped,gzipSync('')]),{maxOutputLength:2097408,rejectGarbageAfterEnd:true})}catch{trailingRejected=true}
console.log(JSON.stringify({node:process.version,utf8Bytes:Buffer.byteLength(raw),utf16Bytes:native,gzipBytes:zipped.length,utf8OnlyWouldGrowUTF16:zipped.length<Buffer.byteLength(raw)&&zipped.length>native,extraGzipMemberRejected:trailingRejected}));db.close();
